from collections import deque, Counter, defaultdict

def get_components_with_tags(grid, bg=3):
    H, W = len(grid), len(grid[0])
    tagged = {}  # (r, c) -> (color, "large" if size>=4 else "small")

    seen = set()
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == bg or (i, j) in seen:
                continue
            comp_cells = []
            comp_range = (0)  # will store size
            q = deque([(i, j)])
            seen.add((i, j))
            while q:
                r, col = q.popleft()
                comp_cells.append((r, col))
                comp_range += 1
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, col + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == c and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if comp_range >= 4:
                for r, col in comp_cells:
                    tagged[(r, col)] = (c, "large")
            else:
                for r, col in comp_cells:
                    tagged[(r, col)] = (c, "small")

    return tagged

