import json
from collections import deque, defaultdict, Counter
import os

def get_bg(grid):
    bg_count = Counter()
    for row in grid:
        for x in row:
            bg_count[x] += 1
    bg = bg_count.most_common(1)[0][0]
    return bg

def find_components(grid):
    H, W = len(grid), len(grid[0])
    seen = set()
    comps = []
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if grid[i][j] == 3 or (i, j) in seen:
                continue  # Skip background
            comp = []
            q = deque([(i, j)])
            seen.add((i, j))
            while q:
                r, col = q.popleft()
                comp.append((r, col))
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, col + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == c and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append((c, comp))
    return comps

def transform(grid):
    H, W = len(grid), len(grid[0])
    bg = get_bg(grid)

    large_bboxes = defaultdict(list)
    seen = set()

    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if (i, j) in seen:
                continue
            comp = []
            q = deque([(i, j)])
            seen.add((i, j))
            while q:
                r, col = q.popleft()
                comp.append((r, col))
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, col + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == c and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if len(comp) >= 4:
                min_r, max_r = min(cell[0] for cell in comp), max(cell[0] for cell in comp)
                min_c, max_c = min(cell[1] for cell in comp), max(cell[1] for cell in comp)
                large_bboxes[c].append((min_r, max_r, min_c, max_c))

    # Fill bbox areas with their colors
    result = [[bg for _ in range(W)] for _ in range(H)]
    for c, bboxes in large_bboxes.items():
        for min_r, max_r, min_c, max_c in bboxes:
            for r in range(min_r, max_r + 1):
                for col in range(min_c, max_c + 1):
                    result[r][col] = c

    return result

